const express = require('express');
const { jwtVerify, createLocalJWKSet } = require('jose');
const db = require('../db');

const app = express();
app.use(express.json());

const jwks = createLocalJWKSet(JSON.parse(process.env.SSO_PUBLIC_JWKS));

const verifyAuth = async (req, res, next) => {
  const token = req.headers.authorization?.replace('Bearer ', '');
  if (!token) return res.status(401).json({ error: 'Missing token' });

  try {
    // Explicitly validate audience and issuer
    const { payload } = await jwtVerify(token, jwks, {
      algorithms: ['RS256'],
      audience: 'account-management-service',
      issuer: 'https://auth.cloudid.io'
    });
    req.user = payload;
    next();
  } catch (err) {
    return res.status(401).json({ error: 'Invalid token' });
  }
};

app.post('/api/user-profiles/:userId/update-email', verifyAuth, async (req, res) => {
  const { userId } = req.params;
  const { newEmail } = req.body;

  // Enforce that user can only update their own email
  if (req.user.sub !== userId) {
    return res.status(403).json({ error: 'Cannot update email for another user account' });
  }

  const updated = await db('users')
    .where({ id: userId })
    .update({ email: newEmail, updated_at: new Date() });

  if (!updated) {
    return res.status(404).json({ error: 'User not found' });
  }

  return res.json({ status: 'Email updated successfully', userId, newEmail });
});

module.exports = app;
